<script setup lang="ts">
import { ref, computed, onMounted, onUnmounted, watch } from 'vue'
import { Activity, ArrowDownRight, ArrowRight, ArrowUpRight, BarChart3, Bell, BookOpen, Box, Check, CheckCircle2, ChevronDown, ChevronRight, CircleHelp, Clock3, Database, Download, FileText, FlaskConical, GitCompareArrows, Layers3, LogOut, Network, Play, Plus, RefreshCw, Search, Settings2, ShieldCheck, Sparkles, Upload, X, XCircle, Zap } from 'lucide-vue-next'
import { api, credentials, clearCredentials, download, type RecordData as R } from './api'

const user=ref<R|null>(null), loginName=ref('admin'), loginPassword=ref('Demo2026!'), loading=ref(false), busy=ref(false), error=ref(''), toast=ref('')
const page=ref('overview'), projectId=ref(''), datasets=ref<R[]>([]), agents=ref<R[]>([]), runs=ref<R[]>([]), reports=ref<R[]>([]), audit=ref<R[]>([])
const selectedDataset=ref(''), selectedRun=ref<R|null>(null), detail=ref<R|null>(null), compare=ref<R|null>(null), baseline=ref(''), candidate=ref(''), filter=ref('ALL'), search=ref('')
const modal=ref(''), reportUrl=ref(''), reportMode=ref('redacted'), reviewReason=ref(''), reviewVerdict=ref('FAIL'), importName=ref(''), importText=ref('')
const runForm=ref({ name:'', dataset_id:'', agent_id:'', max_requests:50, max_retries:0 })
const agentForm=ref({ name:'', adapter:'HTTP', variant:'B', endpoint:'', secret_ref:'', timeout_seconds:30, idempotent:false, capability:'black_box', input_price:null as number|null, output_price:null as number|null, price_version:'unknown' })
const memberName=ref('developer'), memberRole=ref('DEVELOPER'), newProjectName=ref('')
const project=computed(()=>user.value?.projects.find((p:R)=>p.id===projectId.value))
const role=computed(()=>project.value?.members[user.value?.username]||'VIEWER')
const canRun=computed(()=>['ADMIN','DEVELOPER'].includes(role.value)), canReview=computed(()=>['ADMIN','REVIEWER'].includes(role.value)), canImport=computed(()=>['ADMIN','DEVELOPER','REVIEWER'].includes(role.value))
const dataset=computed(()=>datasets.value.find(d=>d.id===selectedDataset.value)||datasets.value[0])
const latest=computed(()=>runs.value[0]), metrics=computed(()=>latest.value?.metrics)
const finished=computed(()=>runs.value.filter(r=>!['QUEUED','RUNNING'].includes(r.status)))
const activeRuns=computed(()=>runs.value.filter(r=>['QUEUED','RUNNING'].includes(r.status)).length)
const compareRows=computed(()=>(compare.value?.rows||[]).filter((r:R)=>(filter.value==='ALL'||r.change===filter.value)&&`${r.input} ${r.case_id}`.toLowerCase().includes(search.value.toLowerCase())))
const resultRows=computed(()=>(selectedRun.value?.results||[]).filter((r:R)=>`${r.case_id} ${r.case.input}`.includes(search.value)))
watch([baseline,candidate],()=>{compare.value=null})
const nav=[{id:'overview',label:'项目概览',icon:Layers3},{id:'datasets',label:'评测数据集',icon:Database},{id:'agents',label:'Agent 配置',icon:Box},{id:'runs',label:'评测批次',icon:FlaskConical},{id:'compare',label:'版本对比',icon:GitCompareArrows},{id:'reports',label:'验收报告',icon:FileText}]
const titles:Record<string,string>={overview:'项目概览',datasets:'评测数据集',agents:'Agent 配置',runs:'评测批次',compare:'版本对比',reports:'验收报告',settings:'项目设置'}
const statuses:Record<string,string>={QUEUED:'排队中',RUNNING:'运行中',COMPLETED:'已完成',COMPLETED_WITH_ERRORS:'完成 · 含异常',CANCELLED:'已取消',SUCCEEDED:'调用成功',CALL_ERROR:'调用错误',PLATFORM_ERROR:'平台错误',NEEDS_REVIEW:'中断待核对',PENDING:'待执行',SCORED:'已评分',UNKNOWN:'无法判断',ERROR:'评分异常',PUBLISHED:'已发布',DRAFT:'草稿',IMPROVED:'改善',REGRESSED:'退化',UNCHANGED:'维持',INCOMPARABLE:'不可比'}
const pct=(n:any)=>typeof n==='number'?`${(n*100).toFixed(1)}%`:'—'
const ms=(n:any)=>typeof n==='number'?`${Math.round(n)} ms`:'—'
const money=(n:any)=>typeof n==='number'?`¥ ${n.toFixed(5)}`:'未知'
const time=(s:string)=>s?new Date(s).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}):'—'
const scoreText=(r:R)=>r?.score?.state==='SCORED'?(r.score.passed?'通过':'失败'):(statuses[r?.score?.state]||'待评')
const scoreClass=(r:R)=>r?.score?.state==='SCORED'?(r.score.passed?'success':'danger'):'warning'
const stateClass=(s:string)=>['COMPLETED','SUCCEEDED','PUBLISHED','IMPROVED'].includes(s)?'success':['CALL_ERROR','PLATFORM_ERROR','REGRESSED'].includes(s)?'danger':['RUNNING','QUEUED'].includes(s)?'info':'warning'
function notify(message:string){toast.value=message;setTimeout(()=>toast.value='',3500)}
async function action(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function login(){loading.value=true;error.value='';try{credentials(loginName.value,loginPassword.value);user.value=await api('/me');projectId.value=user.value!.projects[0]?.id||'';await reload()}catch(e){error.value=(e as Error).message;user.value=null}finally{loading.value=false}}
function logout(){user.value=null;clearCredentials();selectedRun.value=null;compare.value=null;detail.value=null;page.value='overview';error.value=''}
async function reload(){if(!projectId.value)return;const q=`?project_id=${encodeURIComponent(projectId.value)}`;const data=await Promise.all([api('/datasets'+q),api('/agents'+q),api('/runs'+q),api('/reports'+q)]);[datasets.value,agents.value,runs.value,reports.value]=data;if(!datasets.value.some(d=>d.id===selectedDataset.value))selectedDataset.value=datasets.value[0]?.id||''}
async function changeProject(){selectedRun.value=null;compare.value=null;baseline.value='';candidate.value='';await action(reload)}
function go(id:string){page.value=id;search.value='';if(id!=='runs')selectedRun.value=null;if(id==='compare'&&!baseline.value&&finished.value.length>=2){baseline.value=finished.value[1]!.id;candidate.value=finished.value[0]!.id;void action(loadComparison)}}
function newRun(){runForm.value={name:'',dataset_id:datasets.value.find(d=>d.status==='PUBLISHED')?.id||'',agent_id:agents.value[0]?.id||'',max_requests:50,max_retries:0};modal.value='run'}
async function submitRun(){await action(async()=>{const r=await api('/runs','POST',{...runForm.value,project_id:projectId.value}, {'Idempotency-Key':crypto.randomUUID()});modal.value='';await reload();await openRun(r.id);notify('评测已提交，后台将继续执行')})}
async function demo(){await action(async()=>{const ds=datasets.value.find(d=>d.id==='dataset-demo-v1'),a=agents.value.find(a=>a.id==='agent-demo-A'),b=agents.value.find(a=>a.id==='agent-demo-B');if(!ds||!a||!b)throw new Error('当前项目没有预置演示数据，请先创建数据集和 Agent。');const r1=await api('/runs','POST',{project_id:projectId.value,dataset_id:ds.id,agent_id:a.id,name:'客服 v1.0 · 基线回归',max_requests:50,max_retries:0},{'Idempotency-Key':crypto.randomUUID()});const r2=await api('/runs','POST',{project_id:projectId.value,dataset_id:ds.id,agent_id:b.id,name:'客服 v1.1 · 候选回归',max_requests:50,max_retries:0},{'Idempotency-Key':crypto.randomUUID()});baseline.value=r1.id;candidate.value=r2.id;await reload();page.value='runs';selectedRun.value=null;notify('两个评测批次已创建，约 10 秒后可查看对比')})}
async function openRun(id:string){selectedRun.value=await api('/runs/'+id);page.value='runs';search.value=''}
async function cancelRun(){await action(async()=>{await api('/runs/'+selectedRun.value!.id+'/cancel','POST');await openRun(selectedRun.value!.id);await reload();notify('已请求取消，将保留完成结果')})}
async function loadComparison(){if(!baseline.value||!candidate.value)return;compare.value=await api(`/comparisons?baseline_run_id=${baseline.value}&candidate_run_id=${candidate.value}`)}
async function openDetail(r:R){detail.value=await api('/results/'+r.id);reviewReason.value='';reviewVerdict.value='FAIL';modal.value='detail'}
async function submitReview(){await action(async()=>{detail.value=await api('/results/'+detail.value!.id+'/reviews','POST',{verdict:reviewVerdict.value,reason:reviewReason.value});if(selectedRun.value)await openRun(selectedRun.value.id);if(compare.value)await loadComparison();await reload();reviewReason.value='';notify('复核已保存，原评分保留在历史记录中')})}
async function importDataset(){await action(async()=>{const d=await api('/datasets/import','POST',{project_id:projectId.value,name:importName.value,jsonl:importText.value});modal.value='';await reload();selectedDataset.value=d.id;notify('已导入草稿，请审核后发布')})}
async function chooseFile(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(file){if(file.size>500000){error.value='文件不能超过 500 KB';return}importText.value=await file.text();if(!importName.value)importName.value=file.name.replace('.jsonl','')}}
async function publishDataset(){await action(async()=>{await api('/datasets/'+dataset.value!.id+'/publish','POST');await reload();notify('问题集已发布，内容版本已冻结')})}
async function createAgent(){await action(async()=>{await api('/agents','POST',{...agentForm.value,project_id:projectId.value});modal.value='';await reload();notify('Agent 配置快照已创建')})}
async function testAgent(id:string){await action(async()=>{const r=await api('/agents/'+id+'/test','POST');notify(`连接成功 · ${ms(r.duration_ms)} · ${r.has_trace?'有步骤数据':'黑盒接入'} · ${r.has_usage?'有 Token 数据':'Token 未提供'}`)})}
async function createReport(){await action(async()=>{const r=await api('/reports','POST',{baseline_run_id:baseline.value,candidate_run_id:candidate.value,mode:reportMode.value});await reload();await preview(r.id);notify('报告已保存，后续改判不会改变此快照')})}
async function preview(id:string){if(reportUrl.value)URL.revokeObjectURL(reportUrl.value);const html=await api('/reports/'+id+'/html');reportUrl.value=URL.createObjectURL(new Blob([html],{type:'text/html'}));modal.value='report'}
async function downloadReport(id:string){await action(async()=>download(await api('/reports/'+id+'/html'),`AgentLens-${id}.html`))}
async function settings(){page.value='settings';if(role.value==='ADMIN')audit.value=await api('/audit?project_id='+projectId.value)}
async function saveMember(){await action(async()=>{await api('/projects/'+projectId.value+'/members','POST',{username:memberName.value,role:memberRole.value});user.value=await api('/me');await settings();notify('项目成员权限已更新')})}
async function addProject(){await action(async()=>{const p=await api('/projects','POST',{name:newProjectName.value});user.value=await api('/me');projectId.value=p.id;modal.value='';await changeProject();page.value='overview'})}
let timer:ReturnType<typeof setInterval>|undefined
onMounted(()=>{timer=setInterval(async()=>{if(!user.value||busy.value)return;try{await reload();if(selectedRun.value&&['RUNNING','QUEUED'].includes(selectedRun.value.status))selectedRun.value=await api('/runs/'+selectedRun.value.id)}catch{/* Keep the current screen on transient connection loss. */}},2000)})
onUnmounted(()=>{if(timer)clearInterval(timer);if(reportUrl.value)URL.revokeObjectURL(reportUrl.value)})
</script>

<template>
  <div v-if="!user" class="login-shell">
    <div class="login-story"><div class="brand"><div class="brand-symbol"><Activity :size="25"/></div><span>AgentLens<span class="brand-dot">.</span></span></div><div class="login-copy"><span class="eyebrow">EVALUATE. OBSERVE. IMPROVE.</span><h1>让每一次 Agent 迭代，<br>都有据可循。</h1><p>从业务问题到运行链路，从版本变化到验收报告。<br>用可复查的证据，连接研发与业务。</p><div class="login-trace"><div><Database :size="20"/>业务问题集 <CheckCircle2 :size="18"/></div><span></span><div><FlaskConical :size="20"/>A / B 评测 <Activity :size="18"/></div><span></span><div><FileText :size="20"/>验收报告 <ArrowRight :size="18"/></div></div></div><small>AI Agent 评测与可观测性平台 · Demo 0.1</small></div>
    <form class="login-card" @submit.prevent="login"><span class="pill info">本地演示工作空间</span><h2>欢迎进入 AgentLens</h2><p>登录后开始一次可追溯的评测。</p><label>账号<select v-model="loginName"><option value="admin">admin · 管理员</option><option value="developer">developer · 开发者</option><option value="reviewer">reviewer · 评审者</option><option value="outsider">outsider · 隔离验证账号</option></select></label><label>密码<input v-model="loginPassword" type="password" autocomplete="current-password" required/></label><div v-if="error" class="error-box">{{error}}</div><button class="button primary full" :disabled="loading">{{loading?'正在登录…':'进入工作空间'}}<ArrowRight :size="17"/></button><div class="login-note"><ShieldCheck :size="17"/><span>预置演示密码：Demo2026!<br>可在部署配置中修改。</span></div></form>
  </div>
  <div v-else class="app-shell">
    <aside class="sidebar">
      <div class="brand"><div class="brand-symbol"><Activity :size="24"/></div><span>AgentLens<span class="brand-dot">.</span></span></div>
      <div class="workspace-label">WORKSPACE</div><div class="workspace-box"><div class="workspace-avatar">星</div><div><strong>Agent 评测工作台</strong><small>开发与业务协作空间</small></div><ChevronDown :size="15"/></div>
      <div class="nav-label">项目工作台</div><nav><button v-for="item in nav" :key="item.id" :class="{active:page===item.id}" @click="go(item.id)"><component :is="item.icon" :size="19"/><span>{{item.label}}</span><span v-if="item.id==='runs'&&activeRuns" class="nav-count">{{activeRuns}}</span></button></nav>
      <div class="sidebar-bottom"><div class="local-status"><span class="live-dot"></span>本地部署<span>v0.1</span></div><button class="side-setting" @click="action(settings)"><Settings2 :size="18"/>项目与权限</button><div class="profile"><div class="avatar">{{user.username.slice(0,1).toUpperCase()}}</div><div><strong>{{user.username}}</strong><small>{{({ADMIN:'管理员',DEVELOPER:'开发者',REVIEWER:'评审者',VIEWER:'查看者'} as R)[role]}}</small></div><button title="退出登录" class="icon-button" @click="logout"><LogOut :size="17"/></button></div></div>
    </aside>
    <div class="main-shell">
      <header class="topbar"><div class="breadcrumb">工作空间<ChevronRight :size="14"/><select aria-label="选择项目" v-model="projectId" @change="changeProject"><option v-for="p in user.projects" :value="p.id" :key="p.id">{{p.name}}</option></select><ChevronRight :size="14"/><strong>{{titles[page]}}</strong></div><div class="top-actions"><span class="pill outline"><span class="live-dot"></span>本地服务</span><button class="icon-button" title="使用说明" @click="modal='help'"><CircleHelp :size="19"/></button><button class="icon-button" title="刷新数据" @click="action(reload)"><RefreshCw :size="18"/></button></div></header>
      <main>
        <div v-if="error" class="error-box global-error"><span>{{error}}</span><button class="icon-button" @click="error=''" aria-label="关闭错误"><X :size="18"/></button></div>
        <template v-if="page==='overview'">
          <div class="page-heading"><div><div class="eyebrow">PROJECT OVERVIEW</div><h1>每一次迭代，都看得见。</h1><p>跟踪 Agent 质量、定位业务退化，让版本上线更有把握。</p></div><button v-if="canRun" class="button primary" @click="newRun"><Plus :size="18"/>新建评测</button></div>
          <div class="demo-banner"><div class="banner-icon"><Sparkles :size="22"/></div><div><strong>从一次完整的版本对比开始</strong><p>25 条模拟业务问题 · 2 个 Agent 版本 · 可复查的评分与链路 · 离线验收报告</p></div><button v-if="canRun" class="button dark" :disabled="busy" @click="demo"><Play :size="15"/>运行 A/B 演示<ArrowRight :size="16"/></button><span class="banner-tag">模拟数据</span></div>
          <div class="stat-grid"><div class="stat-card"><div class="stat-label">最近批次通过率<CheckCircle2 :size="18"/></div><strong>{{pct(metrics?.pass_rate)}}</strong><small>已判定 {{(metrics?.pass||0)+(metrics?.fail||0)}} / {{metrics?.total||0}} 条</small></div><div class="stat-card"><div class="stat-label">判定覆盖率<BarChart3 :size="18"/></div><strong>{{pct(metrics?.coverage)}}</strong><small>未知与待评独立记录</small><div class="mini-progress"><i :style="{width:(metrics?.coverage||0)*100+'%'}"></i></div></div><div class="stat-card"><div class="stat-label">请求耗时 P95<Clock3 :size="18"/></div><strong>{{ms(metrics?.p95_ms)}}</strong><small>成功请求 · {{metrics?.latency_samples||0}} 个样本</small><div class="tiny-label">NEAREST-RANK</div></div><div class="stat-card"><div class="stat-label">已知调用成本<Zap :size="18"/></div><strong class="cost-number">{{money(metrics?.known_cost)}}</strong><small>成本覆盖率 {{pct(metrics?.cost_coverage)}}</small><div class="tiny-label">CNY · 模拟单价 / 按配置计价</div></div></div>
          <div class="overview-grid"><section class="panel"><div class="panel-heading"><div><h2>最近评测批次<span class="count">{{runs.length}}</span></h2><p>每个批次固定问题集与 Agent 配置快照</p></div><button class="text-button" @click="go('runs')">查看全部<ArrowRight :size="15"/></button></div><div v-if="!runs.length" class="empty-state"><FlaskConical :size="38"/><h3>准备好第一次评测了吗？</h3><p>预置问题集与 A/B 配置已就绪，点击上方运行演示。</p></div><div v-else class="table-wrap"><table><thead><tr><th>批次 / 版本</th><th>状态</th><th>通过率</th><th>时间</th><th></th></tr></thead><tbody><tr v-for="r in runs.slice(0,5)" :key="r.id" @click="action(()=>openRun(r.id))" class="clickable"><td><strong>{{r.name}}</strong><small class="cell-sub">{{r.id}}</small></td><td><span class="pill" :class="stateClass(r.status)">{{statuses[r.status]}}</span></td><td>{{pct(r.metrics.pass_rate)}}</td><td class="muted">{{time(r.created_at)}}</td><td><ChevronRight :size="16"/></td></tr></tbody></table></div></section><section class="panel workflow-panel"><div class="panel-heading"><div><h2>从评测到验收</h2><p>保持一条清晰的证据链</p></div><Network :size="21"/></div><div class="workflow"><button @click="go('datasets')"><span>01</span><div><strong>维护业务问题集</strong><small>{{datasets.length}} 个数据集 · 发布后版本冻结</small></div><ChevronRight :size="16"/></button><button @click="go('runs')"><span>02</span><div><strong>执行与复核</strong><small>业务规则评分，保留人工审核记录</small></div><ChevronRight :size="16"/></button><button @click="go('compare')"><span>03</span><div><strong>比较版本变化</strong><small>改善与退化，一起呈现</small></div><ChevronRight :size="16"/></button><button @click="go('reports')"><span>04</span><div><strong>形成验收报告</strong><small>单文件 HTML，可离线复查</small></div><ChevronRight :size="16"/></button></div><div class="subtle-note"><ShieldCheck :size="17"/>数据缺失会标为未知，不默认计零。</div></section></div>
          <div class="bottom-note"><span><span class="live-dot"></span>数据由本地服务提供 · 每 2 秒刷新</span><span>模拟演示不代表真实企业试点成果</span></div>
        </template>

        <template v-if="page==='datasets'">
          <div class="page-heading"><div><div class="eyebrow">DATASETS</div><h1>让业务标准成为评测依据</h1><p>问题、检查点与参考证据一起版本化，确保每次比较有共同基准。</p></div><button v-if="canImport" class="button primary" @click="modal='import';importName='';importText=''"><Upload :size="17"/>导入问题集</button></div>
          <div class="dataset-layout"><section class="panel dataset-list"><div class="panel-heading"><h2>数据集 <span class="count">{{datasets.length}}</span></h2></div><button v-for="d in datasets" :key="d.id" :class="{selected:dataset?.id===d.id}" @click="selectedDataset=d.id"><div class="dataset-icon"><Database :size="21"/></div><strong>{{d.name}}</strong><small>{{d.cases.length}} 条问题 · {{time(d.created_at)}}</small><span class="pill" :class="stateClass(d.status)">{{statuses[d.status]}}</span></button><div v-if="!datasets.length" class="empty-state">暂无数据集，请导入 JSONL。</div></section><section v-if="dataset" class="panel"><div class="panel-heading"><div><h2>{{dataset.name}}</h2><p>{{dataset.source}}</p></div><div class="button-group"><button class="button secondary" @click="download(dataset.cases.map((c:R)=>JSON.stringify(c)).join('\n'),dataset.id+'.jsonl','application/x-ndjson')"><Download :size="16"/>JSONL</button><button v-if="dataset.status==='DRAFT'&&canImport" class="button primary" :disabled="busy" @click="publishDataset">审核并发布</button></div></div><div class="version-strip"><ShieldCheck :size="16"/><span>{{dataset.status==='PUBLISHED'?'已发布版本 · 内容不可原地修改':'草稿 · 发布前请核查问题和规则'}}</span><code>{{dataset.content_hash?.slice(0,20)||'尚未生成内容 hash'}}</code></div><div class="table-wrap"><table><thead><tr><th>案例 / 问题</th><th>场景</th><th>业务检查点</th></tr></thead><tbody><tr v-for="c in dataset.cases" :key="c.case_id"><td><small class="mono">{{c.case_id}}</small><div>{{c.input}}</div><small class="cell-sub">依据：{{c.evidence?.join('、')||'未提供'}}</small></td><td><span class="pill neutral">{{c.tags?.[0]||'未分类'}}</span></td><td><span v-if="c.checks?.manual" class="pill warning">人工审核</span><span v-else class="muted">{{c.checks?.contains?.join(' / ')||'无文本规则'}}<small v-if="c.checks?.tool" class="cell-sub">工具：{{c.checks.tool}}</small></span></td></tr></tbody></table></div></section></div>
        </template>

        <template v-if="page==='agents'">
          <div class="page-heading"><div><div class="eyebrow">AGENT CONNECTIONS</div><h1>连接你的 Agent</h1><p>固定配置快照，按接口真实能力展示输出、步骤与 Token 数据。</p></div><button v-if="role==='ADMIN'" class="button primary" @click="modal='agent'"><Plus :size="17"/>添加配置</button></div>
          <div class="agent-grid"><section v-for="a in agents" :key="a.id" class="panel agent-card"><div class="agent-card-top"><div class="agent-logo"><Box :size="26"/></div><span class="pill" :class="a.adapter==='MOCK'?'warning':'info'">{{a.adapter==='MOCK'?'模拟 Agent':'HTTP 接入'}}</span></div><h2>{{a.name}}</h2><p>{{a.adapter==='MOCK'?'自建客服示例 · 通过本地 HTTP 实际调用':a.endpoint}}</p><div class="agent-properties"><div><span>可观测能力</span><strong>{{a.capability==='instrumented'?'步骤链路':'黑盒输入输出'}}</strong></div><div><span>请求超时</span><strong>{{a.timeout_seconds}} 秒</strong></div><div><span>幂等声明</span><strong>{{a.idempotent?'支持':'未声明'}}</strong></div><div><span>价格版本</span><strong>{{a.price_version}}</strong></div></div><div class="config-hash"><ShieldCheck :size="14"/>{{a.config_hash.slice(0,24)}}</div><button v-if="canRun" class="button secondary full" :disabled="busy" @click="testAgent(a.id)"><Zap :size="16"/>测试连接</button></section></div><div class="info-callout"><CircleHelp :size="19"/><div><strong>缺少内部链路，也能开始评测。</strong><p>HTTP 黑盒接入可提供回答、调用状态与总耗时。工具正确性需要完整 trace；Token 或价格缺失时，成本显示为未知。</p></div></div>
        </template>

        <template v-if="page==='runs'">
          <div class="page-heading"><div><div class="eyebrow">EVALUATION RUNS</div><h1>{{selectedRun?selectedRun.name:'每一次运行，都保留证据'}}</h1><p>{{selectedRun?selectedRun.id:'后台执行不受页面关闭影响，结果与评分历史持续保存。'}}</p></div><div class="button-group"><button v-if="selectedRun" class="button secondary" @click="selectedRun=null">返回列表</button><button v-if="canRun" class="button primary" @click="newRun"><Plus :size="17"/>新建评测</button></div></div>
          <section v-if="!selectedRun" class="panel"><div class="panel-heading"><h2>全部批次 <span class="count">{{runs.length}}</span></h2><span class="muted">{{activeRuns}} 个正在执行</span></div><div v-if="!runs.length" class="empty-state"><FlaskConical :size="38"/><h3>暂无评测批次</h3><p>使用已发布的问题集创建第一次评测。</p><button v-if="canRun" class="button primary" @click="demo">运行 A/B 演示</button></div><div v-else class="table-wrap"><table><thead><tr><th>批次</th><th>状态 / 进度</th><th>通过率</th><th>判定覆盖率</th><th>P95</th><th>创建时间</th></tr></thead><tbody><tr v-for="r in runs" :key="r.id" class="clickable" @click="action(()=>openRun(r.id))"><td><strong>{{r.name}}</strong><small class="cell-sub">{{r.manifest.source==='SIMULATED'?'模拟运行':'外部 Agent'}} · {{r.id}}</small></td><td><span class="pill" :class="stateClass(r.status)">{{statuses[r.status]}}</span><small class="cell-sub">{{r.metrics.done}} / {{r.metrics.total}} 条</small></td><td>{{pct(r.metrics.pass_rate)}}</td><td>{{pct(r.metrics.coverage)}}</td><td>{{ms(r.metrics.p95_ms)}}</td><td class="muted">{{time(r.created_at)}}</td></tr></tbody></table></div></section>
          <template v-else><div class="run-status panel"><span class="pill" :class="stateClass(selectedRun.status)">{{statuses[selectedRun.status]}}</span><span>已处理 {{selectedRun.metrics.done}} / {{selectedRun.metrics.total}}</span><div class="progress"><i :style="{width:selectedRun.metrics.done/selectedRun.metrics.total*100+'%'}"></i></div><span class="muted">请求 {{selectedRun.request_count}} / {{selectedRun.max_requests}}</span><button v-if="canRun&&['RUNNING','QUEUED'].includes(selectedRun.status)" class="button secondary" :disabled="busy||selectedRun.cancel_requested" @click="cancelRun">{{selectedRun.cancel_requested?'正在取消':'取消运行'}}</button></div><div class="stat-grid compact"><div class="stat-card"><div class="stat-label">已判定通过率</div><strong>{{pct(selectedRun.metrics.pass_rate)}}</strong><small>通过 {{selectedRun.metrics.pass}} · 失败 {{selectedRun.metrics.fail}}</small></div><div class="stat-card"><div class="stat-label">判定覆盖率</div><strong>{{pct(selectedRun.metrics.coverage)}}</strong><small>未知 {{selectedRun.metrics.unknown}} · 待评 {{selectedRun.metrics.pending}}</small></div><div class="stat-card"><div class="stat-label">执行异常</div><strong>{{selectedRun.metrics.call_errors}}</strong><small>与业务失败分别统计</small></div><div class="stat-card"><div class="stat-label">已知调用成本</div><strong class="cost-number">{{money(selectedRun.metrics.known_cost)}}</strong><small>覆盖率 {{pct(selectedRun.metrics.cost_coverage)}}</small></div></div><section class="panel"><div class="panel-heading"><h2>案例结果</h2><div class="search-input"><Search :size="16"/><input v-model="search" placeholder="搜索问题或案例编号"/></div></div><div class="table-wrap"><table><thead><tr><th>案例</th><th>执行状态</th><th>业务判定</th><th>评分理由</th><th>总耗时</th><th></th></tr></thead><tbody><tr v-for="r in resultRows" :key="r.id" class="clickable" @click="action(()=>openDetail(r))"><td><small class="mono">{{r.case_id}}</small><div>{{r.case.input}}</div></td><td><span class="pill" :class="stateClass(r.status)">{{statuses[r.status]}}</span></td><td><span class="pill" :class="scoreClass(r)">{{scoreText(r)}}</span></td><td class="reason-cell">{{r.score.reason}}</td><td class="nowrap">{{ms(r.duration_ms)}}</td><td><ChevronRight :size="16"/></td></tr></tbody></table></div></section><details class="manifest-details"><summary>查看运行配置与版本 manifest</summary><pre>{{JSON.stringify(selectedRun.manifest,null,2)}}</pre></details></template>
        </template>

        <template v-if="page==='compare'">
          <div class="page-heading"><div><div class="eyebrow">VERSION COMPARISON</div><h1>看清进步，也看见退化</h1><p>同一问题集、同一评分版本，按案例配对比较每次变化。</p></div><button v-if="compare" class="button primary" @click="page='reports'"><FileText :size="17"/>生成验收报告</button></div><div class="panel comparison-picker"><label><span class="version-letter">A</span><div>基线版本<select v-model="baseline"><option value="">选择已完成批次</option><option v-for="r in finished" :value="r.id">{{r.name}} · {{time(r.created_at)}}</option></select></div></label><GitCompareArrows :size="23"/><label><span class="version-letter candidate">B</span><div>候选版本<select v-model="candidate"><option value="">选择已完成批次</option><option v-for="r in finished" :value="r.id">{{r.name}} · {{time(r.created_at)}}</option></select></div></label><button class="button primary" :disabled="!baseline||!candidate||busy" @click="action(loadComparison)">开始对比</button></div>
          <div v-if="!compare" class="panel empty-state"><GitCompareArrows :size="40"/><h3>选择两个批次，查看版本变化</h3><p>更换数据集或评分版本时，系统会阻止生成正式差值。</p></div>
          <template v-else><div class="comparison-summary"><div class="panel quality-shift"><div class="stat-label">配对样本通过率 <span class="pill neutral">{{compare.paired}} 条共同判定</span></div><div class="shift-values"><div><small>基线 A</small><strong>{{pct(compare.baseline_paired_rate)}}</strong></div><ArrowRight :size="24"/><div><small>候选 B</small><strong>{{pct(compare.candidate_paired_rate)}}</strong></div><span class="delta" :class="compare.delta>=0?'positive':'negative'">{{compare.delta==null?'—':`${compare.delta>=0?'+':''}${(compare.delta*100).toFixed(1)} pp`}}</span></div><p>完整样本判定覆盖率：A {{pct(compare.baseline_metrics.coverage)}} / B {{pct(compare.candidate_metrics.coverage)}}</p></div><div class="panel change-card"><ArrowUpRight class="green" :size="22"/><strong>{{compare.improved}}</strong><span>改善案例</span></div><div class="panel change-card"><ArrowDownRight class="red" :size="22"/><strong>{{compare.regressed}}</strong><span>退化案例</span></div><div class="panel change-card"><CircleHelp class="amber" :size="22"/><strong>{{compare.incomparable}}</strong><span>无法比较</span></div></div><section class="panel"><div class="panel-heading"><div class="tabs"><button v-for="[id,label] in [['ALL','全部案例'],['REGRESSED','退化'],['IMPROVED','改善'],['UNCHANGED','维持'],['INCOMPARABLE','不可比']]" :class="{active:filter===id}" @click="filter=id!">{{label}}</button></div><div class="search-input"><Search :size="16"/><input v-model="search" placeholder="搜索案例"/></div></div><div class="table-wrap"><table><thead><tr><th>业务问题</th><th>变化</th><th>基线 A</th><th>候选 B</th><th>查看证据</th></tr></thead><tbody><tr v-for="r in compareRows" :key="r.case_id"><td><small class="mono">{{r.case_id}}</small><div>{{r.input}}</div></td><td><span class="pill" :class="stateClass(r.change)">{{statuses[r.change]}}</span></td><td><span class="score-dot" :class="scoreClass(r.baseline)"></span>{{scoreText(r.baseline)}}</td><td><span class="score-dot" :class="scoreClass(r.candidate)"></span>{{scoreText(r.candidate)}}</td><td class="button-group"><button class="text-button" @click="action(()=>openDetail(r.baseline))">A 详情</button><button v-if="r.candidate" class="text-button" @click="action(()=>openDetail(r.candidate))">B 详情<ArrowRight :size="14"/></button></td></tr></tbody></table></div></section></template>
        </template>

        <template v-if="page==='reports'">
          <div class="page-heading"><div><div class="eyebrow">ACCEPTANCE REPORTS</div><h1>把评测结果，交付为可信报告</h1><p>固定版本、样本与评分历史，生成可以离线打开的验收材料。</p></div></div><section class="panel report-create"><div class="report-illustration"><FileText :size="50"/><span>HTML</span></div><div><h2>生成一份版本验收报告</h2><p>包含配对比较、改善与退化案例、覆盖率、已知成本及版本限制。</p><div class="report-controls"><label>基线批次<select v-model="baseline"><option value="">选择基线</option><option v-for="r in finished" :value="r.id">{{r.name}}</option></select></label><label>候选批次<select v-model="candidate"><option value="">选择候选</option><option v-for="r in finished" :value="r.id">{{r.name}}</option></select></label><label>内容范围<select v-model="reportMode"><option value="redacted">脱敏演示 · 隐藏全部业务文本</option><option value="internal">内部完整 · 含问题、回答和依据</option></select></label></div><button class="button primary" :disabled="!baseline||!candidate||busy" @click="createReport"><FileText :size="17"/>生成并预览</button></div></section><section class="panel"><div class="panel-heading"><h2>已保存报告 <span class="count">{{reports.length}}</span></h2><span class="muted">快照不会随评分修订而改变</span></div><div v-if="!reports.length" class="empty-state"><FileText :size="34"/><p>完成 A/B 评测后，即可生成第一份报告。</p></div><table v-else><thead><tr><th>报告</th><th>内容范围</th><th>生成时间</th><th>操作</th></tr></thead><tbody><tr v-for="r in [...reports].reverse()" :key="r.id"><td><strong>{{r.name}}</strong><small class="cell-sub">{{r.id}}</small></td><td><span class="pill neutral">{{r.mode==='redacted'?'脱敏演示':'内部完整'}}</span></td><td>{{time(r.created_at)}}</td><td><div class="button-group"><button class="text-button" @click="action(()=>preview(r.id))">预览</button><button class="text-button" @click="downloadReport(r.id)"><Download :size="15"/>下载 HTML</button></div></td></tr></tbody></table></section>
        </template>

        <template v-if="page==='settings'">
          <div class="page-heading"><div><div class="eyebrow">PROJECT SETTINGS</div><h1>项目与访问权限</h1><p>每一次数据访问均检查项目归属，关键操作留下审计记录。</p></div><button class="button primary" @click="modal='project'"><Plus :size="17"/>创建项目</button></div><section class="panel"><div class="panel-heading"><h2>{{project?.name}}</h2><span class="pill info">{{role}}</span></div><table><thead><tr><th>成员</th><th>项目角色</th></tr></thead><tbody><tr v-for="(r,name) in project?.members" :key="name"><td>{{name}}</td><td>{{r}}</td></tr></tbody></table><div v-if="role==='ADMIN'" class="member-form"><select v-model="memberName"><option>admin</option><option>developer</option><option>reviewer</option><option>outsider</option></select><select v-model="memberRole"><option>ADMIN</option><option>DEVELOPER</option><option>REVIEWER</option><option>VIEWER</option></select><button class="button primary" :disabled="busy" @click="saveMember">保存成员权限</button></div></section><section v-if="role==='ADMIN'" class="panel"><div class="panel-heading"><h2>操作审计</h2></div><div class="table-wrap"><table><thead><tr><th>操作</th><th>操作者</th><th>对象</th><th>时间</th></tr></thead><tbody><tr v-for="a in audit.slice(0,50)" :key="a.id"><td>{{a.action}}</td><td>{{a.actor}}</td><td class="mono">{{a.target}}</td><td>{{time(a.created_at)}}</td></tr></tbody></table></div></section>
        </template>
      </main>
    </div>
  </div>
  <div v-if="toast" class="toast"><CheckCircle2 :size="19"/>{{toast}}</div>
  <div v-if="modal&&user" class="modal-overlay" @click.self="modal=''">
    <section class="modal" :class="{'detail-modal':modal==='detail','report-modal':modal==='report'}" role="dialog" aria-modal="true" :aria-label="modal"><button class="modal-close icon-button" aria-label="关闭弹窗" @click="modal=''"><X :size="22"/></button>
      <div v-if="error" class="error-box">{{error}}</div>
      <template v-if="modal==='run'"><div class="eyebrow">NEW EVALUATION</div><h2>新建评测批次</h2><p>批次创建后，问题集与配置版本将固定。</p><form @submit.prevent="submitRun"><label>批次名称<input v-model="runForm.name" placeholder="例如：客服 v1.1 回归评测" required/></label><label>已发布问题集<select v-model="runForm.dataset_id" required><option v-for="d in datasets.filter(d=>d.status==='PUBLISHED')" :value="d.id">{{d.name}} · {{d.cases.length}} 条</option></select></label><label>Agent 配置<select v-model="runForm.agent_id" required><option v-for="a in agents" :value="a.id">{{a.name}}</option></select></label><div class="form-row"><label>最大请求次数<input v-model.number="runForm.max_requests" type="number" min="1" max="2000" required/></label><label>额外重试次数<select v-model.number="runForm.max_retries"><option :value="0">0 · 不重试</option><option :value="1">1 · 仅幂等且可重试错误</option></select></label></div><div class="subtle-note"><CircleHelp :size="17"/>缺少 Token 时费用未知，以请求次数限制预算。</div><button class="button primary full" :disabled="busy"><Play :size="17"/>提交评测</button></form></template>
      <template v-if="modal==='import'"><div class="eyebrow">IMPORT DATASET</div><h2>导入业务问题集</h2><p>每行一个 JSON 对象，包含 case_id、input 和 checks。</p><form @submit.prevent="importDataset"><label>数据集名称<input v-model="importName" required placeholder="例如：售后客服验收集 v2"/></label><label class="file-zone"><Upload :size="24"/><span>选择 .jsonl 文件</span><input type="file" accept=".jsonl,.ndjson,.txt" @change="chooseFile"/></label><label>JSONL 内容<textarea v-model="importText" rows="10" required placeholder='{"case_id":"CASE-001","input":"如何退款？","checks":{"contains":["7天"]},"reference":"7天内申请退款"}'></textarea></label><button class="button primary full" :disabled="busy">校验并导入草稿</button></form></template>
      <template v-if="modal==='agent'"><div class="eyebrow">NEW AGENT SNAPSHOT</div><h2>添加 Agent 配置快照</h2><form @submit.prevent="createAgent"><label>配置名称<input v-model="agentForm.name" required placeholder="企业客服 v2.0"/></label><div class="form-row"><label>接入方式<select v-model="agentForm.adapter"><option>HTTP</option><option>MOCK</option></select></label><label v-if="agentForm.adapter==='MOCK'">模拟版本<select v-model="agentForm.variant"><option>A</option><option>B</option></select></label><label>超时 / 秒<input type="number" v-model.number="agentForm.timeout_seconds" min="1" max="60"/></label></div><template v-if="agentForm.adapter==='HTTP'"><label>接口地址<input v-model="agentForm.endpoint" placeholder="http://允许列表中的固定IP:端口/agent" required/></label><label>密钥环境变量名<input v-model="agentForm.secret_ref" placeholder="AGENT_SECRET_CUSTOMER（不填写真实密钥）"/></label></template><label>观测能力<select v-model="agentForm.capability"><option value="black_box">黑盒 · 输入输出与总耗时</option><option value="instrumented">支持内部步骤 trace</option></select></label><label class="checkbox"><input type="checkbox" v-model="agentForm.idempotent"/>接口声明支持 Idempotency-Key 幂等执行</label><div class="form-row"><label>输入价格 / 百万 Token<input type="number" min="0" step="any" v-model.number="agentForm.input_price" placeholder="未知则留空"/></label><label>输出价格 / 百万 Token<input type="number" min="0" step="any" v-model.number="agentForm.output_price" placeholder="未知则留空"/></label></div><label>价格表版本<input v-model="agentForm.price_version"/></label><button class="button primary full" :disabled="busy">保存新配置</button></form></template>
      <template v-if="modal==='detail'&&detail"><div class="eyebrow">CASE EVIDENCE / {{detail.case_id}}</div><h2>{{detail.case.input}}</h2><div class="detail-badges"><span class="pill" :class="scoreClass(detail)">{{scoreText(detail)}}</span><span class="pill" :class="stateClass(detail.status)">{{statuses[detail.status]}}</span><span class="pill neutral">{{detail.source==='SIMULATED'?'模拟运行':'运行记录'}}</span><span class="muted">{{ms(detail.duration_ms)}}</span></div><div class="detail-grid"><div><h3>Agent 回答</h3><div class="answer-box">{{detail.output||'未取得回答'}}<small v-if="detail.error_code" class="cell-sub">错误码：{{detail.error_code}}</small></div><h3>参考答案与业务证据</h3><div class="reference-box">{{detail.case.reference||'未提供参考答案'}}<small class="cell-sub">{{detail.case.evidence?.join('、')||'未提供证据'}}</small></div><h3>评分依据</h3><p>{{detail.score.reason}}</p><small class="muted">{{detail.score.source==='HUMAN'?'人工复核 · '+detail.score.reviewer:'确定性业务规则'}} · {{detail.score.evaluator_version}}</small><details><summary>查看检查点与历史记录</summary><pre>{{JSON.stringify(detail.case.checks,null,2)}}</pre><div v-for="s in detail.score_history" class="history-item"><strong>{{s.state}} · {{s.passed==null?'未知':s.passed?'通过':'失败'}}</strong><p>{{s.reason}}</p><small>{{s.created_at}}</small></div></details></div><div><h3><Network :size="18"/>执行链路 <span class="pill neutral">{{detail.trace?.length||0}} 步骤</span></h3><div v-if="detail.trace?.length" class="trace-list"><div v-for="s in detail.trace" :key="s.span_id" class="trace-step" :class="{nested:s.parent_span_id}"><span class="trace-icon"><component :is="s.type==='retrieval'?Search:s.type==='tool'?Settings2:s.type==='model'?Sparkles:Box" :size="15"/></span><div><strong>{{s.name}}</strong><small>{{s.type}} · {{ms(s.duration_ms)}}</small><code v-if="s.args">{{JSON.stringify(s.args)}}</code></div><span class="trace-bar" :style="{width:Math.max(8,Math.min(70,s.duration_ms/(detail.duration_ms||1)*70))+'px'}"></span></div><p v-if="!detail.trace_complete" class="warning-text">链路不完整，缺失父步骤或观测数据。</p></div><div v-else class="no-trace"><Network :size="30"/><strong>无内部观测数据</strong><p>保留输入输出与总耗时，不推断隐藏步骤。</p></div><h3>Token 与尝试</h3><div class="usage-row"><div><small>输入 Token</small><strong>{{detail.usage?.input_tokens??'未知'}}</strong></div><div><small>输出 Token</small><strong>{{detail.usage?.output_tokens??'未知'}}</strong></div><div><small>请求次数</small><strong>{{detail.attempts.length}}</strong></div></div><details><summary>查看调用尝试</summary><pre>{{JSON.stringify(detail.attempts,null,2)}}</pre></details></div></div><form v-if="canReview&&detail.status==='SUCCEEDED'" class="review-form" @submit.prevent="submitReview"><h3><ShieldCheck :size="18"/>人工复核</h3><div class="form-row"><label>判定<select v-model="reviewVerdict"><option value="PASS">通过</option><option value="FAIL">失败</option><option value="UNKNOWN">无法判断</option></select></label><label class="grow">复核理由<input v-model="reviewReason" required placeholder="请写明业务依据或争议原因"/></label><button class="button primary" :disabled="busy">保存复核</button></div><small>修订以新记录追加，原评分及已导出报告保持不变。</small></form></template>
      <template v-if="modal==='report'"><h2>离线报告预览</h2><p>报告已保存。可关闭预览后从报告列表下载。</p><iframe :src="reportUrl" sandbox="" title="验收报告预览"></iframe></template>
      <template v-if="modal==='project'"><h2>创建项目</h2><form @submit.prevent="addProject"><label>项目名称<input v-model="newProjectName" required/></label><button class="button primary full" :disabled="busy">创建</button></form></template>
      <template v-if="modal==='help'"><h2>3 分钟开始一次评测</h2><ol class="help-list"><li>在项目概览点击“运行 A/B 演示”。</li><li>等待两个批次结束，查看案例的业务判定与异常。</li><li>进入版本对比，选择基线 A 和候选 B。</li><li>筛选“退化”，打开 B 详情查看回答、规则与步骤。</li><li>由管理员或评审者填写人工复核理由。</li><li>生成验收报告，选择脱敏范围并下载 HTML。</li></ol><div class="info-callout">预置样本、Agent 和价格均为模拟数据。真实企业接入需配置服务器允许列表与环境变量密钥。</div></template>
    </section>
  </div>
</template>
